import { AsyncPipe, CommonModule } from '@angular/common';
import { ChangeDetectionStrategy, Component } from '@angular/core';
import { DanaToastNotice, DanaToastService } from './dana-toast.service';
@Component({ selector: 'dana-toast-host, gear-toast-host', standalone: true, imports:[CommonModule,AsyncPipe], changeDetection:ChangeDetectionStrategy.OnPush, template:`<div class="dana-toast-stack gear-toast-stack" aria-live="polite" aria-relevant="additions removals"><article *ngFor="let notice of toast.notices$ | async; trackBy: trackById" class="dana-toast gear-toast" [class.toast-success]="notice.tone === 'success'" [class.toast-warning]="notice.tone === 'warning'" [class.toast-error]="notice.tone === 'error'" [class.toast-info]="notice.tone === 'info'" [attr.role]="notice.tone === 'error' ? 'alert' : 'status'"><div class="dana-toast-icon gear-toast-icon" aria-hidden="true">{{ notice.tone === 'success' ? '✓' : notice.tone === 'warning' ? '!' : notice.tone === 'error' ? '!' : 'i' }}</div><div class="dana-toast-copy gear-toast-copy"><strong>{{ notice.title }}</strong><span>{{ notice.message }}</span></div><button type="button" class="dana-toast-close gear-toast-close" aria-label="Dismiss notification" (click)="toast.dismiss(notice.id)">×</button></article></div>` })
export class DanaToastHostComponent { constructor(public readonly toast:DanaToastService){} trackById(_i:number,n:DanaToastNotice){return n.id} }
